const performanceMetricNames=new Set(['navigationMs','playbackNavigationMs','surfaceHideMs','surfaceSyncMs','firstFrameMs','bufferingDurationMs','bufferingCount','playerLoadAcceptedMs']);
function recordPerformanceMetric(metric:string,value:number):void{if(!performanceMetricNames.has(metric)||!Number.isFinite(value)||value<0||value>120_000)return;const items=performanceSamples.get(metric)??[];items.push(Math.round(value*10)/10);if(items.length>200)items.splice(0,items.length-200);performanceSamples.set(metric,items);}
function p95(values:number[]):number{if(!values.length)return 0;const ordered=[...values].sort((a,b)=>a-b);return ordered[Math.min(ordered.length-1,Math.max(0,Math.ceil(ordered.length*.95)-1))]??0;}
function performanceSummary():Record<string,{count:number;latest:number;p95:number}>{const out:Record<string,{count:number;latest:number;p95:number}>={};for(const[metric,values]of performanceSamples)out[metric]={count:values.length,latest:values.at(-1)??0,p95:p95(values)};return out;}
function broadcastPlaybackStage(stage:string,message:string,error?:string):void{mainWindow?.webContents.send('playback:stageChanged',{stage,message,...(error?{error}:{}),at:Date.now()});}
async function measureFirstFrame(started:number):Promise<void>{for(let attempt=0;attempt<20;attempt++){await new Promise(resolve=>setTimeout(resolve,100));try{const stats=await player.query('stats');if((stats.width??0)>0&&(stats.height??0)>0){recordPerformanceMetric('firstFrameMs',performance.now()-started);return;}}catch{return;}}}
const playbackResolutionCache=new Map<string,{resolved:PlayResult;resolution:PlaybackResolution;expiresAt:number}>();
const liveRouteCache=new Map<string,{routeIndex:number;expiresAt:number}>();
const PLAYBACK_RESOLUTION_TTL_MS=2*60*1000;
const LIVE_ROUTE_TTL_MS=30*60*1000;
function playbackCacheKey(sourceId:string,flag:string,episodeId:string):string{return sourceId+'\u0000'+flag+'\u0000'+episodeId;}
function liveRouteKey(sourceId:string,channelId:string):string{return sourceId+'\u0000'+channelId;}
function prunePlaybackCaches():void{const now=Date.now();for(const[key,item]of playbackResolutionCache)if(item.expiresAt<=now)playbackResolutionCache.delete(key);for(const[key,item]of liveRouteCache)if(item.expiresAt<=now)liveRouteCache.delete(key);}
function rememberPlaybackResolution(key:string,resolved:PlayResult,resolution:PlaybackResolution):void{if(playbackResolutionCache.size>=256){const oldest=playbackResolutionCache.keys().next().value as string|undefined;if(oldest)playbackResolutionCache.delete(oldest);}playbackResolutionCache.set(key,{resolved,resolution,expiresAt:Date.now()+PLAYBACK_RESOLUTION_TTL_MS});}
function rememberLiveRoute(key:string,routeIndex:number):void{if(liveRouteCache.size>=512){const oldest=liveRouteCache.keys().next().value as string|undefined;if(oldest)liveRouteCache.delete(oldest);}liveRouteCache.set(key,{routeIndex,expiresAt:Date.now()+LIVE_ROUTE_TTL_MS});}
function clearLiveRouteCache(sourceId:string):void{const prefix=sourceId+'\u0000';for(const key of liveRouteCache.keys())if(key.startsWith(prefix))liveRouteCache.delete(key);}
let quitting=false;
